  return SyncCrypto.concat(SyncCrypto.bytes("PrivateInput/clipboard-live-certificate/v1\0"),new byte[]{1},SyncCrypto.uuid(c.getString("group")),SyncCrypto.uuid(c.getString("parent")),SyncCrypto.be(SyncCrypto.u(c,"epoch")),SyncCrypto.uuid(c.getString("generation")),SyncCrypto.data(c,"signingPublic"),SyncCrypto.data(c,"delegatePublic"),SyncCrypto.be(SyncCrypto.u(c,"issuedAt")),SyncCrypto.be(SyncCrypto.u(c,"expiresAt")));
