  c.put("signature",SyncCrypto.b64(SyncCrypto.sign(certificateBytes(c),SyncCrypto.privateKey("Ed25519",identity.getString("signing")))));return new JSONObject().put("certificate",c).put("private",SyncCrypto.b64(pair.getPrivate().getEncoded()));
